//! Test archives tracked in `testdata/` (generated by the maintainers; do not edit them by hand): no
//! game data, invented test key.
#![allow(dead_code)]

use std::path::PathBuf;

/// File in `testdata/`, at the root of the p4kr repository.
pub fn testdata(name: &str) -> PathBuf {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../testdata")
        .join(name);
    assert!(
        path.is_file(),
        "{} missing: testdata/ is incomplete",
        path.display()
    );
    path
}

pub struct Synth {
    pub archive: PathBuf,
    pub key: PathBuf,
    pub expected: Vec<serde_json::Value>,
}

pub fn synth() -> Synth {
    let expected = std::fs::read_to_string(testdata("expected.json")).expect("expected.json");
    Synth {
        archive: testdata("synth.p4k"),
        key: testdata("synth.key.toml"),
        expected: serde_json::from_str(&expected).expect("JSON"),
    }
}
